    if (user.role !== "doctor") {
      throw new Error("User is not a doctor");
    }
    if (data.image !== undefined) {
      await prisma_default.user.update({
        where: { id: data.userId },
        data: { image: data.image }
      });
    }
    if (data.gender !== undefined || data.dateOfBirth !== undefined || data.phone !== undefined || data.address !== undefined) {
      await prisma_default.userInfo.upsert({
        where: { userId: data.userId },
        update: {
          gender: data.gender,
          dateOfBirth: data.dateOfBirth,
          phone: data.phone,
          address: data.address
        },
        create: {
          userId: data.userId,
          gender: data.gender,
          dateOfBirth: data.dateOfBirth,
          phone: data.phone,
          address: data.address
        }
      });
    }
