init_prisma();
var import_agora_token = __toESM(require_agora_token(), 1);
var AGORA_SERVICES = {
  generateRoleBasedUid(appointmentId, userRole) {
    const appointmentHash = appointmentId.split("").reduce((hash2, char) => {
      return (hash2 << 5) - hash2 + char.charCodeAt(0) & 268435455;
    }, 0);
    const rolePrefix = userRole === "doctor" ? 1 : 2;
    const uid = parseInt(`${rolePrefix}${Math.abs(appointmentHash).toString().slice(-8)}`, 10);
    return uid > 0 ? uid : Math.abs(uid) + 1e6;
  },
  async generateToken(params) {
    const { appointmentId, userId, userRole } = params;
    const appointment = await prisma_default.appointment.findUnique({
      where: { id: appointmentId },
      include: {
        doctor: { select: { id: true, name: true } },
        patient: { select: { id: true, name: true } }
      }
    });
    if (!appointment) {
      throw new Error("Appointment not found");
    }
    if (!appointment.scheduledAt) {
      throw new Error("Appointment has no scheduled time");
    }
    if (userRole === "doctor" && appointment.doctorId !== userId) {
      throw new Error("Unauthorized: User is not the doctor for this appointment");
    }
    if (userRole === "patient" && appointment.patientId !== userId) {
      throw new Error("Unauthorized: User is not the patient for this appointment");
    }
    const now = new Date;
    const appointmentStartTime = new Date(appointment.scheduledAt);
    const appointmentEndTime = new Date(appointmentStartTime.getTime() + 15 * 60 * 1000);
    const earliestAccess = new Date(appointmentStartTime.getTime() - 30 * 60 * 1000);
    const latestAccess = new Date(appointmentEndTime.getTime() + 30 * 60 * 1000);
    if (now < earliestAccess) {
      const minutesUntilAccess = Math.ceil((earliestAccess.getTime() - now.getTime()) / (1000 * 60));
      throw new Error(`Token can only be generated ${minutesUntilAccess} minutes before the appointment starts`);
    }
    if (now > latestAccess) {
      throw new Error("The appointment access window has expired");
    }
    const uid = this.generateRoleBasedUid(appointmentId, userRole);
    const existingTokenRecord = await this.findValidToken(appointmentId, now);
    if (existingTokenRecord) {
      const existingToken = userRole === "doctor" ? existingTokenRecord.doctorToken : existingTokenRecord.patientToken;
      if (existingToken) {
        return {
          token: existingToken,
          channel: existingTokenRecord.channel,
          uid,
          appId: Bun.env.AGORA_APP_ID || "",
          expiry: existingTokenRecord.expiry,
          isExisting: true
        };
      }
    }
    const channelName = appointmentId;
    const agoraRole = import_agora_token.RtcRole.PUBLISHER;
    const tokenExpireTime = Math.floor(latestAccess.getTime() / 1000);
    const token = import_agora_token.RtcTokenBuilder.buildTokenWithUid(Bun.env.AGORA_APP_ID || "", Bun.env.AGORA_CERTIFICATE_ID || "", channelName, uid, agoraRole, tokenExpireTime, tokenExpireTime);
    await this.saveToken({
      appointmentId,
      channel: channelName,
      [userRole === "doctor" ? "doctorToken" : "patientToken"]: token,
      [userRole === "doctor" ? "doctorUid" : "patientUid"]: uid,
      expiry: latestAccess
    });
    return {
      token,
      channel: channelName,
      uid,
      appId: Bun.env.AGORA_APP_ID || "",
      expiry: latestAccess,
      isExisting: false
    };
  },
  async findValidToken(appointmentId, currentTime) {
    return await prisma_default.agoraToken.findFirst({
      where: {
        appointmentId,
        expiry: {
          gt: currentTime
        }
      },
      orderBy: {
        createdAt: "desc"
      }
    });
  },
  async saveToken(data) {
    const existingRecord = await prisma_default.agoraToken.findFirst({
      where: { appointmentId: data.appointmentId }
    });
    if (existingRecord) {
      return await prisma_default.agoraToken.update({
        where: { id: existingRecord.id },
        data: {
          doctorToken: data.doctorToken ?? existingRecord.doctorToken,
          patientToken: data.patientToken ?? existingRecord.patientToken,
          doctorUid: data.doctorUid ?? existingRecord.doctorUid,
          patientUid: data.patientUid ?? existingRecord.patientUid,
          expiry: data.expiry
        }
      });
    } else {
      return await prisma_default.agoraToken.create({
        data: {
          appointmentId: data.appointmentId,
          channel: data.channel,
          doctorToken: data.doctorToken,
          patientToken: data.patientToken,
          doctorUid: data.doctorUid,
          patientUid: data.patientUid,
          expiry: data.expiry,
          joinedFirst: ""
        }
      });
    }
  },
  async updateJoinStatus(appointmentId, _userId, userRole, action) {
    const now = new Date;
    const updateData = {};
    if (action === "joined") {
      if (userRole === "doctor") {
        updateData.doctorJoined = now;
      } else {
        updateData.patientJoined = now;
      }
    } else if (action === "ended") {
      if (userRole === "doctor") {
        updateData.doctorEnded = now;
      } else {
        updateData.patientEnded = now;
      }
    }
    const token = await prisma_default.agoraToken.findFirst({
      where: { appointmentId },
      orderBy: { createdAt: "desc" }
    });
    if (!token) {
      throw new Error("No token found for appointment");
    }
    if (action === "joined" && !token.doctorJoined && !token.patientJoined) {
      updateData.joinedFirst = userRole;
    }
    return await prisma_default.agoraToken.update({
      where: { id: token.id },
      data: updateData
    });
  },
  async getTokenStats(appointmentId) {
    return await prisma_default.agoraToken.findFirst({
      where: { appointmentId },
      orderBy: { createdAt: "desc" },
      select: {
        id: true,
        channel: true,
        doctorToken: true,
        patientToken: true,
        doctorUid: true,
        patientUid: true,
        expiry: true,
        patientJoined: true,
        doctorJoined: true,
        patientEnded: true,
        doctorEnded: true,
        joinedFirst: true,
        createdAt: true
      }
    });
  },
  async cleanupExpiredTokens() {
    const now = new Date;
    return await prisma_default.agoraToken.deleteMany({
      where: {
        expiry: {
          lt: now
        }
      }
    });
  },
  async validateAppointmentAccess(appointmentId) {
    const appointment = await prisma_default.appointment.findUnique({
      where: { id: appointmentId }
    });
    if (!appointment || !appointment.scheduledAt) {
      return {
        isValid: false,
        canAccess: false,
        message: "Appointment not found or has no scheduled time"
      };
    }
    const now = new Date;
    const startTime = new Date(appointment.scheduledAt);
    const endTime = new Date(startTime.getTime() + 15 * 60 * 1000);
    const earliestAccess = new Date(startTime.getTime() - 30 * 60 * 1000);
    const latestAccess = new Date(endTime.getTime() + 30 * 60 * 1000);
    const canAccess = now >= earliestAccess && now <= latestAccess;
    let message = "";
    if (now < earliestAccess) {
      const minutesUntil = Math.ceil((earliestAccess.getTime() - now.getTime()) / (1000 * 60));
      message = `Access available in ${minutesUntil} minutes`;
    } else if (now > latestAccess) {
      message = "Access window has expired";
    } else {
      message = "Access granted";
    }
    return {
      isValid: true,
      canAccess,
      appointment: {
        startTime,
        endTime,
        earliestAccess,
        latestAccess
      },
      message
    };
  }
};

// src/routes/agora/agora.handlers.ts
var AGORA_ROUTES_HANDLER = {
  getToken: async (c2) => {
    const user = c2.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    const { appointmentId } = c2.req.valid("param");
    try {
      const userRole = user.role;
      const tokenResult = await AGORA_SERVICES.generateToken({
        appointmentId,
        userId: user.id,
        userRole
      });
      return c2.json({
        message: tokenResult.isExisting ? "Existing token retrieved" : "New token generated successfully",
        token: tokenResult.token,
        channel: tokenResult.channel,
        uid: tokenResult.uid,
        appId: tokenResult.appId,
        expiry: tokenResult.expiry.toISOString(),
        isExisting: tokenResult.isExisting
      }, OK);
    } catch (error43) {
      if (error43 instanceof HttpError) {
        throw error43;
      }
      const errorMessage = error43 instanceof Error ? error43.message : "Unknown error";
      if (errorMessage.includes("Appointment not found")) {
        throw new HttpError("Appointment not found", NOT_FOUND);
      }
      if (errorMessage.includes("Unauthorized")) {
        throw new HttpError(errorMessage, FORBIDDEN);
      }
      if (errorMessage.includes("Token can only be generated") || errorMessage.includes("access window")) {
        throw new HttpError(errorMessage, BAD_REQUEST);
      }
      console.error("Agora service error:", error43);
      throw new HttpError("Failed to generate token", INTERNAL_SERVER_ERROR);
    }
  },
  validateAccess: async (c2) => {
    const { appointmentId } = c2.req.valid("param");
    try {
      const accessValidation = await AGORA_SERVICES.validateAppointmentAccess(appointmentId);
      const responseData = {
        message: accessValidation.message || "Validation completed",
        isValid: accessValidation.isValid,
        canAccess: accessValidation.canAccess,
        appointment: accessValidation.appointment ? {
          startTime: accessValidation.appointment.startTime.toISOString(),
          endTime: accessValidation.appointment.endTime.toISOString(),
          earliestAccess: accessValidation.appointment.earliestAccess.toISOString(),
          latestAccess: accessValidation.appointment.latestAccess.toISOString()
        } : undefined
      };
      return c2.json(responseData, OK);
    } catch (error43) {
      console.error("Agora access validation error:", error43);
      throw new HttpError("Failed to validate access", INTERNAL_SERVER_ERROR);
    }
  },
  getTokenStats: async (c2) => {
    const user = c2.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    const { appointmentId } = c2.req.valid("param");
    try {
      const tokenStats = await AGORA_SERVICES.getTokenStats(appointmentId);
      if (!tokenStats) {
        throw new HttpError("No token found for appointment", NOT_FOUND);
      }
      const responseData = {
        message: "Token statistics retrieved successfully",
        id: tokenStats.id,
        channel: tokenStats.channel,
        doctorToken: tokenStats.doctorToken,
        patientToken: tokenStats.patientToken,
        doctorUid: tokenStats.doctorUid,
        patientUid: tokenStats.patientUid,
        expiry: tokenStats.expiry.toISOString(),
        patientJoined: tokenStats.patientJoined?.toISOString() || null,
        doctorJoined: tokenStats.doctorJoined?.toISOString() || null,
        patientEnded: tokenStats.patientEnded?.toISOString() || null,
        doctorEnded: tokenStats.doctorEnded?.toISOString() || null,
        joinedFirst: tokenStats.joinedFirst,
        createdAt: tokenStats.createdAt.toISOString()
      };
      return c2.json(responseData, OK);
    } catch (error43) {
      if (error43 instanceof HttpError) {
        throw error43;
      }
      console.error("Agora token stats error:", error43);
      throw new HttpError("Failed to retrieve token statistics", INTERNAL_SERVER_ERROR);
    }
  }
};

