var convertDocumentsToSignedUrls2 = async (documents) => {
  if (!documents) {
    return null;
  }
  const keys = [
    extractS3KeyFromUrl(documents.resume),
    extractS3KeyFromUrl(documents.medicalLicense),
    extractS3KeyFromUrl(documents.introductionVideo)
  ].filter((key) => key !== null);
  if (keys.length === 0) {
    return {
      id: documents.id,
      resume: documents.resume,
      medicalLicense: documents.medicalLicense,
      introductionVideo: documents.introductionVideo
    };
  }
  const signedUrls = await keysToSignedUrls(keys, 7 * 24 * 3600);
  const signedUrlsArray = Array.isArray(signedUrls) ? signedUrls : [signedUrls];
  let urlIndex = 0;
  return {
    id: documents.id,
    resume: documents.resume ? signedUrlsArray[urlIndex++] || documents.resume : documents.resume,
    medicalLicense: documents.medicalLicense ? signedUrlsArray[urlIndex++] || documents.medicalLicense : documents.medicalLicense,
    introductionVideo: documents.introductionVideo ? signedUrlsArray[urlIndex++] || documents.introductionVideo : documents.introductionVideo
  };
};
var convertEducationDocumentToSignedUrl2 = async (documentUrl) => {
  if (!documentUrl) {
    return null;
  }
  const key = extractS3KeyFromUrl(documentUrl);
  if (!key) {
    return null;
  }
  return keysToSignedUrls(key, 7 * 24 * 3600);
};
var convertUserImageToSignedUrl2 = async (imageKeyOrUrl) => {
  if (!imageKeyOrUrl) {
    return null;
  }
  if (imageKeyOrUrl.startsWith("http://") || imageKeyOrUrl.startsWith("https://")) {
    return imageKeyOrUrl;
  }
  const key = extractS3KeyFromUrl(imageKeyOrUrl);
  if (!key) {
    return imageKeyOrUrl;
  }
  const signedUrl = await keysToSignedUrls(key, 7 * 24 * 3600);
  return Array.isArray(signedUrl) ? signedUrl[0] : signedUrl;
};
var formatFullAppointmentResponse = async (appointment, currentUserId) => {
  const isViewingOwnAppointment = !!(currentUserId && (appointment.doctorId === currentUserId || appointment.patientId === currentUserId));
  const doctorUser = appointment.doctor;
  const doctorImage = await convertUserImageToSignedUrl2(doctorUser.image);
  let doctorDetails = null;
  if (doctorUser.doctor) {
    const documents = await convertDocumentsToSignedUrls2(doctorUser.doctor.documents);
    const education = await Promise.all((doctorUser.doctor.education || []).map(async (edu) => ({
      ...edu,
      document: await convertEducationDocumentToSignedUrl2(edu.document)
    })));
    doctorDetails = {
      id: doctorUser.doctor.id,
      userid: doctorUser.doctor.userid,
      professional_contact: doctorUser.doctor.professional_contact,
      professional_email: doctorUser.doctor.professional_email,
      about: doctorUser.doctor.about,
      isAvailable: doctorUser.doctor.isAvailable,
      isInMeeting: doctorUser.doctor.isInMeeting,
      availableDurations: doctorUser.doctor.availableDurations,
      documents,
      education,
      professionalExperience: doctorUser.doctor.professionalExperience || []
    };
  }
  const formattedDoctor = {
    id: doctorUser.id,
    name: doctorUser.name,
    email: doctorUser.email,
    image: doctorImage,
    role: doctorUser.role,
    isAnonymous: doctorUser.isAnonymous,
    employeeCode: doctorUser.employeeCode,
    userInfo: doctorUser.userInfo,
    doctor: doctorDetails
  };
  const patientUser = appointment.patient;
  const patientImage = await convertUserImageToSignedUrl2(patientUser.image);
  const formattedPatient = {
    id: patientUser.id,
    name: patientUser.name,
    email: patientUser.email,
    image: patientImage,
    role: patientUser.role,
    isAnonymous: patientUser.isAnonymous,
    employeeCode: patientUser.employeeCode,
    userInfo: patientUser.userInfo
  };
  const anonymizedDoctor = formatUserForAppointment(formattedDoctor, "doctor", isViewingOwnAppointment && appointment.doctorId === currentUserId);
  const anonymizedPatient = formatUserForAppointment(formattedPatient, "patient", isViewingOwnAppointment && appointment.patientId === currentUserId);
  const finalDoctor = {
    ...anonymizedDoctor,
    isAnonymous: formattedDoctor.isAnonymous,
    userInfo: formattedDoctor.userInfo,
    doctor: formattedDoctor.doctor
  };
  const finalPatient = {
    ...anonymizedPatient,
    isAnonymous: formattedPatient.isAnonymous,
    userInfo: formattedPatient.userInfo
  };
  const uploadIdSignedUrl = appointment.uploadId ? await convertUserImageToSignedUrl2(appointment.uploadId) : null;
  const baseAppointment = {
    id: appointment.id,
    doctorId: appointment.doctorId,
    patientId: appointment.patientId,
    status: appointment.status,
    scheduledAt: appointment.scheduledAt?.toISOString() || null,
    startedAt: appointment.startedAt?.toISOString() || null,
    endedAt: appointment.endedAt?.toISOString() || null,
    createdAt: appointment.createdAt.toISOString(),
    updatedAt: appointment.updatedAt.toISOString(),
    chatroomExpiry: appointment.chatroomExpiry?.toISOString() || null,
    age: appointment.age,
    appointmentFor: appointment.appointmentFor,
    issue: appointment.issue,
    uploadId: uploadIdSignedUrl,
    relationWithPatient: appointment.relationWithPatient,
    patientName: appointment.patientName,
    patientAge: appointment.patientAge
  };
  if (isViewingOwnAppointment) {
    if (appointment.doctorId === currentUserId) {
      return {
        ...baseAppointment,
        doctor: formattedDoctor,
        patient: finalPatient
      };
    } else {
      return {
        ...baseAppointment,
        doctor: finalDoctor,
        patient: formattedPatient
      };
    }
  }
  return {
    ...baseAppointment,
    doctor: finalDoctor,
    patient: finalPatient
  };
};
var formatAppointmentResponse = async (appointment, currentUserId) => {
  const isViewingOwnAppointment = !!(currentUserId && (appointment.doctorId === currentUserId || appointment.patientId === currentUserId));
  const doctorForFormat = appointment.doctor ? {
    ...appointment.doctor,
    image: await convertUserImageToSignedUrl2(appointment.doctor.image)
  } : appointment.doctor;
  const patientForFormat = appointment.patient ? {
    ...appointment.patient,
    image: await convertUserImageToSignedUrl2(appointment.patient.image)
  } : appointment.patient;
  const uploadIdSignedUrl = appointment.uploadId ? await convertUserImageToSignedUrl2(appointment.uploadId) : null;
  return {
    id: appointment.id,
    doctorId: appointment.doctorId,
    patientId: appointment.patientId,
    status: appointment.status,
    scheduledAt: appointment.scheduledAt?.toISOString() || null,
    startedAt: appointment.startedAt?.toISOString() || null,
    endedAt: appointment.endedAt?.toISOString() || null,
    createdAt: appointment.createdAt.toISOString(),
    updatedAt: appointment.updatedAt.toISOString(),
    chatroomExpiry: appointment.chatroomExpiry?.toISOString() || null,
    age: appointment.age,
    appointmentFor: appointment.appointmentFor,
    issue: appointment.issue,
    uploadId: uploadIdSignedUrl,
    relationWithPatient: appointment.relationWithPatient,
    patientName: appointment.patientName,
    patientAge: appointment.patientAge,
    doctor: formatUserForAppointment(doctorForFormat, "doctor", isViewingOwnAppointment && appointment.doctorId === currentUserId),
    patient: formatUserForAppointment(patientForFormat, "patient", isViewingOwnAppointment && appointment.patientId === currentUserId)
  };
};
