// src/lib/generate-enterprise-code.ts
init_prisma();
function generateCodeFromName(name) {
  const cleaned = name.replace(/[^a-zA-Z0-9]/g, "").toUpperCase();
  let letters = cleaned.slice(0, 3);
  if (letters.length < 3) {
    letters = letters.padEnd(3, "X");
  }
  const numbers = Math.floor(100 + Math.random() * 900).toString();
  return `${letters}${numbers}`;
}
async function generateUniqueEnterpriseCode(name, maxAttempts = 10) {
  for (let attempt = 0;attempt < maxAttempts; attempt++) {
    const code2 = generateCodeFromName(name);
    const existingEnterprise = await prisma_default.enterprise.findUnique({
      where: { code: code2 }
    });
    if (!existingEnterprise) {
      return code2;
    }
    const letters = code2.slice(0, 3);
    const randomNumbers = Math.floor(100 + Math.random() * 900).toString();
    const newCode = `${letters}${randomNumbers}`;
    const existingEnterprise2 = await prisma_default.enterprise.findUnique({
      where: { code: newCode }
    });
    if (!existingEnterprise2) {
      return newCode;
    }
  }
  throw new Error("Failed to generate unique enterprise code after multiple attempts");
}

// src/services/enterprise.service.ts
var ENTERPRISE_SERVICES = {
  getByCode: async (code2) => {
    const enterprise = await prisma_default.enterprise.findUnique({
      where: { code: code2 }
    });
    return enterprise;
  },
  create: async (data) => {
    const existingByName = await prisma_default.enterprise.findFirst({
      where: {
        name: {
          equals: data.name,
          mode: "insensitive"
        }
      }
    });
    if (existingByName) {
      throw new Error("Enterprise name already exists");
    }
    let code2 = data.code || "";
    if (data.generateCode || !code2) {
      code2 = await generateUniqueEnterpriseCode(data.name);
    }
    if (code2 && !data.generateCode) {
      const existing = await prisma_default.enterprise.findUnique({
        where: { code: code2 }
      });
      if (existing) {
        throw new Error("Enterprise code already exists");
      }
    }
    if (!code2) {
      throw new Error("Enterprise code is required");
    }
    const enterprise = await prisma_default.enterprise.create({
      data: {
        name: data.name,
        code: code2,
        sessionsPerMonth: data.sessionsPerMonth
      }
    });
    return enterprise;
  },
  getAll: async (filters) => {
    const page = filters?.page || 1;
    const limit = filters?.limit || 10;
    const skip = (page - 1) * limit;
    const where = filters?.search ? {
      OR: [
        { name: { contains: filters.search, mode: "insensitive" } },
        { code: { contains: filters.search, mode: "insensitive" } }
      ]
    } : {};
    const [enterprises, total] = await Promise.all([
      prisma_default.enterprise.findMany({
        where,
        orderBy: { createdAt: "desc" },
        skip,
        take: limit
      }),
      prisma_default.enterprise.count({ where })
    ]);
    return {
      enterprises,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit)
      }
    };
  },
  getById: async (id) => {
    const enterprise = await prisma_default.enterprise.findUnique({
      where: { id }
    });
    return enterprise;
  },
  update: async (id, data) => {
    if (data.name) {
      const existingByName = await prisma_default.enterprise.findFirst({
        where: {
          name: {
            equals: data.name,
            mode: "insensitive"
          },
          NOT: { id }
        }
      });
      if (existingByName) {
        throw new Error("Enterprise name already exists");
      }
    }
    if (data.code) {
      const existing = await prisma_default.enterprise.findFirst({
        where: {
          code: data.code,
          NOT: { id }
        }
      });
      if (existing) {
        throw new Error("Enterprise code already exists");
      }
    }
    const enterprise = await prisma_default.enterprise.update({
      where: { id },
      data
    });
    return enterprise;
  },
  delete: async (id) => {
    await prisma_default.enterprise.delete({
      where: { id }
    });
  }
};

