var AUTH_ROUTES_HANDLER = {
  patientSignup: async (c2) => {
    const { name, email: email3, password, enterpriseCode } = c2.req.valid("json");
    const enterprise = await ENTERPRISE_SERVICES.getByCode(enterpriseCode);
    if (!enterprise) {
      throw new HttpError("Invalid enterprise code", BAD_REQUEST);
    }
    const existingUser = await prisma_default.user.findUnique({
      where: { email: email3 }
    });
    if (existingUser) {
      throw new HttpError("Email already exists", CONFLICT);
    }
    const employeeCode = await generateUniqueEmployeeCode(enterpriseCode);
    try {
      const signupResult = await auth.api.signUpEmail({
        body: {
          email: email3,
          password,
          name
        }
      });
      if (!signupResult || !signupResult.user) {
        throw new HttpError("Failed to create user account", INTERNAL_SERVER_ERROR);
      }
      const updatedUser = await prisma_default.user.update({
        where: { id: signupResult.user.id },
        data: {
          role: "patient",
          enterpriseCode,
          employeeCode,
          onboardingStage: "USER_INFO"
        }
      });
      const formattedResponse = {
        id: updatedUser.id,
        name: updatedUser.name,
        email: updatedUser.email,
        role: updatedUser.role,
        enterpriseCode: updatedUser.enterpriseCode,
        employeeCode: updatedUser.employeeCode,
        onboardingStage: updatedUser.onboardingStage
      };
      return c2.json({
        message: "Patient signed up successfully",
        success: true,
        data: formattedResponse
      }, CREATED);
    } catch (error44) {
      const errorMessage = error44 instanceof Error ? error44.message : "Unknown error";
      if (errorMessage.includes("already exists") || errorMessage.includes("duplicate")) {
        throw new HttpError("Email already exists", CONFLICT);
      }
      throw new HttpError(errorMessage || "Failed to create patient account", INTERNAL_SERVER_ERROR);
    }
  },
  doctorSignup: async (c2) => {
    const { name, email: email3, password } = c2.req.valid("json");
    const existingUser = await prisma_default.user.findUnique({
      where: { email: email3 }
    });
    if (existingUser) {
      throw new HttpError("Email already exists", CONFLICT);
    }
    try {
      const signupResult = await auth.api.signUpEmail({
        body: {
          email: email3,
          password,
          name
        }
      });
      if (!signupResult || !signupResult.user) {
        throw new HttpError("Failed to create user account", INTERNAL_SERVER_ERROR);
      }
      const updatedUser = await prisma_default.user.update({
        where: { id: signupResult.user.id },
        data: {
          role: "doctor",
          onboardingStage: "DOCTOR_INFO"
        }
      });
      const formattedResponse = {
        id: updatedUser.id,
        name: updatedUser.name,
        email: updatedUser.email,
        role: updatedUser.role,
        onboardingStage: updatedUser.onboardingStage
      };
      return c2.json({
        message: "Doctor signed up successfully",
        success: true,
        data: formattedResponse
      }, CREATED);
    } catch (error44) {
      const errorMessage = error44 instanceof Error ? error44.message : "Unknown error";
      if (errorMessage.includes("already exists") || errorMessage.includes("duplicate")) {
        throw new HttpError("Email already exists", CONFLICT);
      }
      throw new HttpError(errorMessage || "Failed to create doctor account", INTERNAL_SERVER_ERROR);
    }
  }
};

