var EDUCATION_SERVICES = {
  bulkCreate: async (data) => {
    const doctor2 = await prisma_default.doctor.findUnique({
      where: { id: data.doctorId },
      select: { id: true }
    });
    if (!doctor2) {
      throw new Error("Doctor not found");
    }
    const createdEducations = await prisma_default.$transaction(data.educations.map((education) => prisma_default.education.create({
      data: {
        doctorId: data.doctorId,
        degree: education.degree,
        startYear: education.startYear,
        endYear: education.endYear,
        document: education.document,
        institution_name: education.institution_name
      }
    })));
    return createdEducations;
  },
  getAllByDoctorId: async (doctorId) => {
    const educations = await prisma_default.education.findMany({
      where: { doctorId },
      orderBy: { startYear: "desc" }
    });
    return educations;
  },
  getById: async (id) => {
    const education = await prisma_default.education.findUnique({
      where: { id },
      include: {
        doctor: {
          select: {
            id: true,
            userid: true,
            professional_email: true
          }
        }
      }
    });
    return education;
  },
  update: async (data) => {
    const education = await prisma_default.education.findUnique({
      where: { id: data.id },
      select: { doctorId: true }
    });
    if (!education) {
      throw new Error("Education not found");
    }
    if (education.doctorId !== data.doctorId) {
      throw new Error("Unauthorized: Education does not belong to this doctor");
    }
    const updatedEducation = await prisma_default.education.update({
      where: { id: data.id },
      data: {
        degree: data.degree,
        startYear: data.startYear,
        endYear: data.endYear,
        document: data.document,
        institution_name: data.institution_name
      }
    });
    return updatedEducation;
  },
  delete: async (data) => {
    const education = await prisma_default.education.findUnique({
      where: { id: data.id },
      select: { doctorId: true }
    });
    if (!education) {
      throw new Error("Education not found");
    }
    if (education.doctorId !== data.doctorId) {
      throw new Error("Unauthorized: Education does not belong to this doctor");
    }
    await prisma_default.education.delete({
      where: { id: data.id }
    });
    return { success: true };
  }
};

