var USER_SERVICES = {
  updateRole: async (data) => {
    const user = await prisma_default.user.update({
      where: { id: data.userId },
      data: {
        role: data.role,
        onboardingStage: "USER_INFO"
      }
    });
    return user;
  },
  createOrUpdateUserInfo: async (data) => {
    const user = await prisma_default.user.findUnique({
      where: { id: data.userId },
      select: { role: true }
    });
    if (!user) {
      throw new Error("User not found");
    }
    const userInfo = await prisma_default.userInfo.upsert({
      where: { userId: data.userId },
      update: {
        gender: data.gender,
        dateOfBirth: data.dateOfBirth,
        phone: data.phone,
        address: data.address
      },
      create: {
        userId: data.userId,
        gender: data.gender,
        dateOfBirth: data.dateOfBirth,
        phone: data.phone,
        address: data.address
      }
    });
    let onboardingStage;
    if (user.role === "doctor") {
      onboardingStage = "DOCTOR_INFO";
    } else if (user.role === "patient") {
      onboardingStage = "COMPLETED";
    } else {
      onboardingStage = "USER_INFO";
    }
    await prisma_default.user.update({
      where: { id: data.userId },
      data: { onboardingStage }
    });
    return userInfo;
  },
  getUserInfo: async (userId) => {
    const userInfo = await prisma_default.userInfo.findUnique({
      where: { userId },
      include: {
        user: {
          select: {
            id: true,
            name: true,
            email: true,
            image: true,
            role: true,
            isAnonymous: true,
            employeeCode: true
          }
        }
      }
    });
    return userInfo;
  },
  toggleAnonymousMode: async (userId) => {
    const user = await prisma_default.user.findUnique({
      where: { id: userId },
      select: { role: true, isAnonymous: true }
    });
    if (!user) {
      throw new Error("User not found");
    }
    if (user.role !== "patient") {
      throw new Error("Only patients can use anonymous mode");
    }
    const newAnonymousStatus = !user.isAnonymous;
    const updatedUser = await prisma_default.user.update({
      where: { id: userId },
      data: {
        isAnonymous: newAnonymousStatus
      },
      select: {
        id: true,
        name: true,
        email: true,
        image: true,
        role: true,
        isAnonymous: true,
        employeeCode: true
      }
    });
    return updatedUser;
  }
};

