// src/services/user-query.service.ts
init_prisma();
var USER_QUERY_SERVICES = {
  create: async (data) => {
    const userQuery = await prisma_default.userQuery.create({
      data: {
        message: data.message,
        name: data.name,
        number: data.number,
        email: data.email,
        userId: data.userId || null
      }
    });
    return userQuery;
  },
  getAll: async (filters) => {
    const page = filters?.page || 1;
    const limit = filters?.limit || 10;
    const skip = (page - 1) * limit;
    const where = {};
    if (filters?.search) {
      where.OR = [
        { name: { contains: filters.search, mode: "insensitive" } },
        { email: { contains: filters.search, mode: "insensitive" } },
        { number: { contains: filters.search, mode: "insensitive" } },
        { message: { contains: filters.search, mode: "insensitive" } }
      ];
    }
    const [userQueries, total] = await Promise.all([
      prisma_default.userQuery.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: "desc" },
        include: {
          user: {
            select: {
              id: true,
              name: true,
              email: true
            }
          }
        }
      }),
      prisma_default.userQuery.count({ where })
    ]);
    return {
      userQueries,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit)
      }
    };
  },
  getById: async (id) => {
    const userQuery = await prisma_default.userQuery.findUnique({
      where: { id },
      include: {
        user: {
          select: {
            id: true,
            name: true,
            email: true
          }
        }
      }
    });
    return userQuery;
  },
  delete: async (id) => {
    const userQuery = await prisma_default.userQuery.delete({
      where: { id }
    });
    return userQuery;
  }
};

// src/routes/user-query/user-query.handlers.ts
var formatUserQueryResponse = (query) => ({
  id: query.id,
  message: query.message,
  name: query.name,
  number: query.number,
  email: query.email,
  userId: query.userId,
  createdAt: query.createdAt.toISOString(),
  updatedAt: query.updatedAt.toISOString(),
  user: query.user ? {
    id: query.user.id,
    name: query.user.name,
    email: query.user.email
  } : null
});
var USER_QUERY_ROUTES_HANDLER = {
  create: async (c2) => {
    const user = c2.get("user");
    const { message: message2, name, number: number5, email: email3 } = c2.req.valid("json");
    const userQuery = await USER_QUERY_SERVICES.create({
      message: message2,
      name,
      number: number5,
      email: email3,
      userId: user?.id || null
    });
    return c2.json({
      message: "User query created successfully",
      success: true,
      data: formatUserQueryResponse(userQuery)
    }, CREATED);
  },
  getAll: async (c2) => {
    const user = c2.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "admin") {
      throw new HttpError("Forbidden - Admin only", FORBIDDEN);
    }
    const query = c2.req.valid("query");
    const filters = {
      page: query.page ? parseInt(query.page, 10) : 1,
      limit: query.limit ? parseInt(query.limit, 10) : 10,
      search: query.search
    };
    const result = await USER_QUERY_SERVICES.getAll(filters);
    return c2.json({
      message: "User queries retrieved successfully",
      success: true,
      data: {
        userQueries: result.userQueries.map(formatUserQueryResponse),
        pagination: result.pagination
      }
    }, OK);
  },
  getById: async (c2) => {
    const user = c2.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "admin") {
      throw new HttpError("Forbidden - Admin only", FORBIDDEN);
    }
    const { id } = c2.req.valid("param");
    const userQuery = await USER_QUERY_SERVICES.getById(id);
    if (!userQuery) {
      throw new HttpError("User query not found", NOT_FOUND);
    }
    return c2.json({
      message: "User query retrieved successfully",
      success: true,
      data: formatUserQueryResponse(userQuery)
    }, OK);
  },
  delete: async (c2) => {
    const user = c2.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "admin") {
      throw new HttpError("Forbidden - Admin only", FORBIDDEN);
    }
    const { id } = c2.req.valid("param");
    try {
      await USER_QUERY_SERVICES.delete(id);
      return c2.json({
        message: "User query deleted successfully",
        success: true
      }, OK);
    } catch (error44) {
      if (error44 instanceof Error && "code" in error44 && error44.code === "P2025") {
        throw new HttpError("User query not found", NOT_FOUND);
      }
      throw error44;
    }
  }
};

