// src/lib/configure-open-api.ts
function configureOpenAPI(app) {
  app.doc("/doc", {
    openapi: "3.0.0",
    info: {
      version: "1",
      title: "API Docs"
    }
  });
  app.get("/reference", Scalar({
    theme: "kepler",
    layout: "modern",
    url: "/doc",
    showSidebar: true,
    hideModels: true,
    hideDownloadButton: false,
    hideTestRequestButton: false,
    searchHotKey: "k",
    hiddenClients: true,
    hideClientButton: true,
    defaultHttpClient: {
      targetKey: "js",
      clientKey: "fetch"
    },
    authentication: {
      preferredSecurityScheme: "bearerAuth"
    }
  }));
}

// src/lib/appointment-no-show-cron.ts
class AppointmentNoShowCron {
  checkInterval = null;
  checkIntervalMs = 5 * 60 * 1000;
  start() {
    if (this.checkInterval) {
      console.log("[No-Show Cron] Already running");
      return;
    }
    console.log("[No-Show Cron] Starting - will check every 5 minutes for appointments past 20-minute mark");
    this.checkNoShowAppointments();
    this.checkInterval = setInterval(() => {
      this.checkNoShowAppointments();
    }, this.checkIntervalMs);
  }
  stop() {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
      console.log("[No-Show Cron] Stopped");
    }
  }
  async checkNoShowAppointments() {
    try {
      const result = await APPOINTMENT_SERVICES.markNoShowAppointments();
      if (result.marked > 0) {
        console.log(`[No-Show Cron] Check completed at ${new Date().toISOString()} - Marked ${result.marked} appointment(s) as NO_SHOW`);
      }
    } catch (error44) {
      console.error("[No-Show Cron] Error checking for no-show appointments:", error44);
    }
  }
}
var appointmentNoShowCron = new AppointmentNoShowCron;

